CREATE TABLE IF NOT EXISTS production_release_attempts (version_id TEXT NOT NULL, candidate_commit TEXT NOT NULL, manifest_checksum TEXT NOT NULL, attempt INTEGER NOT NULL CHECK (attempt > 0), idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK (status IN ('pending', 'running', 'succeeded', 'failed')), started_at TEXT NOT NULL, completed_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, failure_fingerprint TEXT, PRIMARY KEY (version_id, candidate_commit, manifest_checksum, attempt));
CREATE TABLE IF NOT EXISTS production_release_targets (version_id TEXT NOT NULL, candidate_commit TEXT NOT NULL, manifest_checksum TEXT NOT NULL, platform TEXT NOT NULL CHECK (platform IN ('web', 'api', 'ios')), app_id TEXT NOT NULL, attempt INTEGER NOT NULL CHECK (attempt > 0), stage TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('pending', 'running', 'succeeded', 'failed')), artifact_identity TEXT, production_readback_sha TEXT, production_release_id TEXT, app_store_app_id TEXT, bundle_id TEXT, marketing_version TEXT, build_number TEXT, processing_status TEXT, processing_id TEXT, review_status TEXT, upload_id TEXT, review_id TEXT, release_status TEXT, release_id TEXT, live_status TEXT, live_id TEXT, sanitized_observed_evidence TEXT CHECK (sanitized_observed_evidence IS NULL OR json_valid(sanitized_observed_evidence)), failure_fingerprint TEXT, started_at TEXT NOT NULL, completed_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (version_id, candidate_commit, manifest_checksum, platform, app_id, attempt), CHECK ((platform IN ('web', 'api') AND app_id = '' AND stage IN ('preflight', 'upload', 'switch', 'health', 'readback') AND artifact_identity IS NOT NULL) OR (platform = 'ios' AND app_id <> '' AND stage IN ('test', 'archive', 'upload', 'processing', 'review_submit', 'review_wait', 'release', 'live_readback') AND app_store_app_id IS NOT NULL AND bundle_id IS NOT NULL AND marketing_version IS NOT NULL AND build_number IS NOT NULL)));
CREATE INDEX IF NOT EXISTS idx_production_release_targets_latest ON production_release_targets (version_id, candidate_commit, manifest_checksum, platform, app_id, attempt DESC);
CREATE INDEX IF NOT EXISTS idx_production_release_targets_reusable_success ON production_release_targets (version_id, candidate_commit, manifest_checksum, platform, app_id, attempt DESC) WHERE status = 'succeeded' AND ((platform IN ('web', 'api') AND stage = 'readback') OR (platform = 'ios' AND stage = 'live_readback'));
CREATE TRIGGER IF NOT EXISTS production_release_attempts_immutable_succeeded BEFORE UPDATE ON production_release_attempts WHEN OLD.status = 'succeeded' BEGIN SELECT RAISE(ABORT, 'immutable succeeded production release attempt'); END;
CREATE TRIGGER IF NOT EXISTS production_release_targets_immutable_succeeded BEFORE UPDATE ON production_release_targets WHEN OLD.status = 'succeeded' BEGIN SELECT RAISE(ABORT, 'immutable succeeded production release target'); END;
